+
+FROM_LINE_COMMENT
+    : LINE_COMMENT -> channel(HIDDEN)
+    ;
+
+FROM_MULTILINE_COMMENT
+    : MULTILINE_COMMENT -> channel(HIDDEN)
+    ;
+
+FROM_WS
+    : WS -> channel(HIDDEN)
+    ;
